BANNED = {"float","round","math","cmath","decimal","random","os","sys","socket",
          "urllib","requests","subprocess","eval","exec","open","__import__","complex"}

def abort(c,d): raise Abort(c,d)
def guard_source(src):
    for tok in tokenize.generate_tokens(StringIO(src).readline):
        k,s = tok.type, tok.string
