      "tolerance":"none","deps":{"python":platform.python_version(),"packages":"stdlib only"},
      "R_source_sha256": hashlib.sha256(src.encode()).hexdigest() if src else None})
    print(json.dumps(cert,sort_keys=True,indent=2))
    sys.exit(0 if cert.get("result")=="PASS" else 1)    # fail-closed exit code
